/*
 * Popular Dineout — Menu Schema + Seed Data
 *
 * Run this in the Supabase SQL Editor (Dashboard > SQL Editor > New Query).
 * It creates three tables, enables RLS with public read access, and inserts
 * all 14 categories, 185 menu items, and 7 combo thalis.
 *
 * Tables:
 *   menu_categories — 14 rows (13 regular + 1 combo-thalis section)
 *   menu_items      — 185 regular menu items
 *   combo_thalis    — 7 combo thali entries
 *
 * Security:
 *   RLS enabled on all tables.
 *   SELECT policies for anon + authenticated (public read).
 *   No write policies — data is managed via SQL only.
 */

CREATE TABLE IF NOT EXISTS menu_categories (
  id text PRIMARY KEY,
  label text NOT NULL,
  short_label text NOT NULL,
  sort_order int NOT NULL DEFAULT 0,
  is_combo boolean NOT NULL DEFAULT false
);

ALTER TABLE menu_categories ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "public_read_menu_categories" ON menu_categories;
CREATE POLICY "public_read_menu_categories"
  ON menu_categories FOR SELECT TO anon, authenticated USING (true);

CREATE TABLE IF NOT EXISTS menu_items (
  id text PRIMARY KEY,
  category_id text NOT NULL REFERENCES menu_categories(id) ON DELETE CASCADE,
  name text NOT NULL,
  description text NOT NULL DEFAULT '',
  price int NOT NULL,
  price_full int,
  image text NOT NULL,
  image_alt text NOT NULL DEFAULT '',
  diet text NOT NULL DEFAULT 'veg',
  spice text,
  popular boolean NOT NULL DEFAULT false,
  chef_special boolean NOT NULL DEFAULT false,
  serves text,
  sort_order int NOT NULL DEFAULT 0
);

ALTER TABLE menu_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "public_read_menu_items" ON menu_items;
CREATE POLICY "public_read_menu_items"
  ON menu_items FOR SELECT TO anon, authenticated USING (true);

CREATE TABLE IF NOT EXISTS combo_thalis (
  id text PRIMARY KEY,
  name text NOT NULL,
  description text NOT NULL DEFAULT '',
  price int NOT NULL,
  image text NOT NULL,
  image_alt text NOT NULL DEFAULT '',
  diet text NOT NULL DEFAULT 'veg',
  serves text NOT NULL DEFAULT '',
  items text[] NOT NULL DEFAULT '{}',
  popular boolean NOT NULL DEFAULT false,
  sort_order int NOT NULL DEFAULT 0
);

ALTER TABLE combo_thalis ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "public_read_combo_thalis" ON combo_thalis;
CREATE POLICY "public_read_combo_thalis"
  ON combo_thalis FOR SELECT TO anon, authenticated USING (true);

CREATE INDEX IF NOT EXISTS idx_menu_items_category_id ON menu_items(category_id);
CREATE INDEX IF NOT EXISTS idx_menu_items_sort_order ON menu_items(category_id, sort_order);
CREATE INDEX IF NOT EXISTS idx_menu_categories_sort_order ON menu_categories(sort_order);
CREATE INDEX IF NOT EXISTS idx_combo_thalis_sort_order ON combo_thalis(sort_order);

-- Insert 14 categories (13 regular + 1 combo-thalis)
ON CONFLICT (id) DO NOTHING;

-- Insert 185 menu items
ON CONFLICT (id) DO NOTHING;

-- Insert 7 combo thalis
ON CONFLICT (id) DO NOTHING;

